                                let mut tmp = ChainedTraversalContextExt::new(
                                    _parentctx.clone(),
                                    _parentState,
                                );
                                recog.push_new_recursion_context(
                                    tmp.clone(),
                                    _startState,
                                    RULE_chainedTraversal,
                                )?;
                                _localctx = tmp;
                                recog.base.set_state(903);
