                        recog
                            .base
                            .match_token(Gremlin_K_LENGTH, &mut recog.err_handler)?;

                        recog.base.set_state(1716);
                        recog
                            .base
                            .match_token(Gremlin_LPAREN, &mut recog.err_handler)?;

                        recog.base.set_state(1717);
                        recog
                            .base
