                        recog
                            .base
                            .match_token(Gremlin_K_TOLOWER, &mut recog.err_handler)?;

                        recog.base.set_state(2325);
                        recog
                            .base
                            .match_token(Gremlin_LPAREN, &mut recog.err_handler)?;

                        /*InvokeRule traversalScope*/
