//------------------- traversalPredicate ----------------
pub type TraversalPredicateContextAll<'input> = TraversalPredicateContext<'input>;

pub type TraversalPredicateContext<'input> =
    BaseParserRuleContext<'input, TraversalPredicateContextExt<'input>>;

#[derive(Clone)]
pub struct TraversalPredicateContextExt<'input> {
    ph: PhantomData<&'input str>,
}

impl<'input> GremlinParserContext<'input> for TraversalPredicateContext<'input> {}

impl<'input, 'a> Listenable<dyn GremlinListener<'input> + 'a>
    for TraversalPredicateContext<'input>
{
    fn enter(&self, listener: &mut (dyn GremlinListener<'input> + 'a)) -> Result<(), ANTLRError> {
        listener.enter_every_rule(self)?;
        listener.enter_traversalPredicate(self);
        Ok(())
    }
    fn exit(&self, listener: &mut (dyn GremlinListener<'input> + 'a)) -> Result<(), ANTLRError> {
        listener.exit_traversalPredicate(self);
        listener.exit_every_rule(self)?;
        Ok(())
    }
}

impl<'input, 'a> Visitable<dyn GremlinVisitor<'input> + 'a> for TraversalPredicateContext<'input> {
    fn accept(&self, visitor: &mut (dyn GremlinVisitor<'input> + 'a)) {
        visitor.visit_traversalPredicate(self);
    }
}

impl<'input> CustomRuleContext<'input> for TraversalPredicateContextExt<'input> {
    type TF = LocalTokenFactory<'input>;
    type Ctx = GremlinParserContextType;
    fn get_rule_index(&self) -> usize {
        RULE_traversalPredicate
    }
    //fn type_rule_index() -> usize where Self: Sized { RULE_traversalPredicate }
}
antlr4rust::tid! {TraversalPredicateContextExt<'a>}

impl<'input> TraversalPredicateContextExt<'input> {
    fn new(
        parent: Option<Rc<dyn GremlinParserContext<'input> + 'input>>,
        invoking_state: i32,
    ) -> Rc<TraversalPredicateContextAll<'input>> {
        Rc::new(BaseParserRuleContext::new_parser_ctx(
            parent,
            invoking_state,
            TraversalPredicateContextExt { ph: PhantomData },
        ))
    }
}

